import{z as i,x as l,o as s,c as d,q as o,j as n,D as e,d as r,s as m,S as p}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"POSIX 共享内存","description":"","frontmatter":{"title":"POSIX 共享内存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/posix-shm.md","filePath":"cs/posix-shm.md","lastUpdated":1791413859000}'),E={name:"cs/posix-shm.md"};function c(h,a,B,A,_,f){const t=l("Mermaid");return s(),d("div",null,[a[2]||(a[2]=o('<h1 id="posix-共享内存" tabindex="-1">POSIX 共享内存 <a class="header-anchor" href="#posix-共享内存" aria-label="Permalink to &quot;POSIX 共享内存&quot;">​</a></h1><div class="epigraph"><p>shm_open 得到一块命名的共享内存对象，mmap 之后各方 load/store 同一物理页，内核不再拷贝载荷。</p><footer>—— 据 POSIX 共享内存；Stevens；Silberschatz 对共享内存 IPC 的整理</footer></div><p><a href="/cs/unix-socket">上一课</a>仍把字节拷进内核缓冲。<a href="/cs/mmap">mmap</a> 已能把文件接到地址空间。<a href="/cs/anon-vs-file-page">匿名页</a> 说明无文件后备时走交换。缺口是<strong>命名共享内存</strong>：像文件可 <code>mmap</code>，又通常不经普通磁盘 FS，供无亲缘进程会合。同步仍要用户自备（后课已有的锁/futex 在用户态用）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>管道与 Unix 域的吞吐受拷贝与系统调用限制。共享页：一次映射，之后是内存访问。<span class="marginnote">直觉类比：管道传数据像两个人靠传纸条沟通——每张纸条都要有人抄送一遍；共享内存像两人面前放同一块白板，一方写下去另一方抬头就能看见。白板（共享页）省掉了全部抄写，但「什么时候写、写完谁看」的规矩（同步锁）得自己定。</span><a href="/cs/cow-fork">COW</a> 是私有副本；这里要 <code>MAP_SHARED</code>。缺口：<code>shm_open(name)</code> 在 shm 命名空间（常挂在 tmpfs）创建对象，<code>ftruncate</code> 定长，各方 <code>mmap</code>。页按需填零，脏了像匿名或像 tmpfs 文件——实现把它们接到页 Cache 或 shmem。</p><p>本课不把 System V <code>shmget</code> 的 key 分配写成第二套主干。</p><p><span class="marginnote">对象有模式位，权限检查与普通文件类似。unlink 名字后，已映射者仍可用，直到最后 unmap——类似 inode 链接计数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建者 <code>shm_open</code> + 截断 + mmap。使用者按名打开再 mmap 到自己的 VA，物理帧共享，<a href="/cs/tlb-translate">TLB</a> 各进程各自翻译到同一 PPN。写立即可见，无内核缓冲边界。互斥：用户放 futex 或信号量在共享页里；内核不管业务锁。</p>',9)),(s(),n(p,null,{default:e(()=>[m(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22shm_open%20%E5%90%8D%22%5D%20--%3E%20OBJ%5B%22%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98%20inode%22%5D%0A%20%20OBJ%20--%3E%20MAP%5B%22%E5%90%84%E6%96%B9%20mmap%22%5D%0A%20%20MAP%20--%3E%20PPN%5B%22%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">「tmpfs」翻译成大白话：一个完全住在内存里的文件系统，文件随断电消失、读写不碰磁盘。shm 对象常驻在它里面，所以既有名字、能用文件的权限模型，又保有纯内存的速度——这就是「像文件可 mmap，又不走普通磁盘 FS」的含义。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>POSIX shm 把「文件映射」用在 IPC：命名走 <a href="/cs/vfs">VFS</a>（tmpfs），数据走页 Cache/匿名 LRU，隔离仍靠各进程页表只映射约定区间。相对套接字：延迟低、无消息边界、错误不会变成 <code>read</code> 返回值。过度提交同样适用：映射成功不等于帧已全部在。</p><p>名字的生命周期是一条单行道——<code>shm_unlink</code> 只摘名字，不回收内存：</p>',4)),(s(),n(p,null,{default:e(()=>[m(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22shm_unlink(name)%22%5D%20--%3E%20B%5B%22%E5%90%8D%E5%AD%97%E4%BB%8E%E5%91%BD%E5%90%8D%E7%A9%BA%E9%97%B4%E6%B6%88%E5%A4%B1%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%96%B0%20shm_open%20%E5%90%8C%E5%90%8D%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20B%20--%3E%20D%5B%22%E5%B7%B2%E6%98%A0%E5%B0%84%E8%BF%9B%E7%A8%8B%E7%85%A7%E5%B8%B8%E8%AF%BB%E5%86%99%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%90%84%E8%BF%9B%E7%A8%8B%E4%BE%9D%E6%AC%A1%20munmap%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%9C%80%E5%90%8E%E4%B8%80%E4%B8%AA%E8%A7%A3%E9%99%A4%E5%90%8E%E5%AF%B9%E8%B1%A1%E6%89%8D%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">常见误区：初学者以为 <code>shm_unlink</code> 之后别人手里的映射会失效甚至崩溃。实际规则与文件的 inode 链接计数一样：名字没了只是「查无此号」，已经映射的进程继续用同一批物理页，直到最后一个人解除映射，内存才真正归还。这既是清理残留对象的依据，也是意外泄漏内存的常见来源。</span></p><p>不要把这写成绕过权限的教程。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 memfd、跨 pidfd 密封的全部 Linux 扩展。不保证实时无缺页——首次触碰仍可能缺页。下一课：一个线程要等许多 fd（套接字、管道、设备）上的可读，不能为每个 fd 开线程。</p><p>后课默认：大块载荷可共享映射。等待多个描述符就绪，下一课 select/poll。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>shm_open + mmap 让无亲缘进程共享物理页。</li><li>内核不拷贝载荷；同步是用户的责任。</li><li>多路等待是 select/poll 的缺口。</li><li>出处：POSIX shared memory；Stevens；Silberschatz et al., <em>OSC</em>。</li></ul>',7))])}const P=i(E,[["render",c]]);export{S as __pageData,P as default};
